/*
 * @lc app=leetcode id=1307 lang=kotlin
 *
 * [1307] Verbal Arithmetic Puzzle
 */
class Solution { fun isSolvable(words: Array<String>, result: String): Boolean = (words + result).flatMap { it.toList() }.distinct().let { rawChars -> if (rawChars.size > 10) false else (words + result).filter { it.length > 1 }.map { it[0] }.toSet().let { nonZero -> rawChars.sortedByDescending { c -> kotlin.math.abs(words.sumOf { w -> w.fold(0L) { a, ch -> a * 10 + if (ch == c) 1 else 0 } } - result.fold(0L) { a, ch -> a * 10 + if (ch == c) 1 else 0 }) }.let { chars -> chars.map { c -> words.sumOf { w -> w.fold(0L) { a, ch -> a * 10 + if (ch == c) 1 else 0 } } - result.fold(0L) { a, ch -> a * 10 + if (ch == c) 1 else 0 } }.let { weights -> DeepRecursiveFunction<Triple<Int, Int, Long>, Boolean> { (idx, mask, sum) -> if (idx == chars.size) sum == 0L else (0..9).any { d -> (mask and (1 shl d)) == 0 && !(d == 0 && chars[idx] in nonZero) && callRecursive(Triple(idx + 1, mask or (1 shl d), sum + d * weights[idx])) } }(Triple(0, 0, 0L)) } } } } }